 1	import type { HttpEffect } from "alchemy/Http";
 2	import { ByteSize, Cause, Effect, Option, Stream } from "effect";
 3	import { HttpClientRequest, HttpServerResponse } from "effect/http";
 4	
 5	import {
 6	  McpResponseDeadline,
 7	  McpResponseLimit,
 8	  McpResponseTooLarge,
 9	} from "./mcp.schemas.js";
10	
11	// The selected tools return complete replies. Read native JSON/SSE framing
12	// inside the native request Scope, with a byte cap and one total deadline.
13	// No subscription, resumption or unbounded event stream is advertised.
14	export const withBoundedMcpReply = Effect.fnUntraced(function* (
15	  handler: HttpEffect
16	) {
17	  return yield* handler.pipe(
18	    Effect.flatMap((response) =>
19	      HttpServerResponse.toClientResponse(response, {
20	        request: HttpClientRequest.post("/mcp"),
21	      }).stream.pipe(
22	        Stream.mapAccumEffect(
23	          () => ByteSize.bytes(0),
24	          (total, chunk) => {
25	            const next = ByteSize.sum(total, ByteSize.bytes(chunk.byteLength));
26	            return ByteSize.isGreaterThan(next, McpResponseLimit)
27	              ? Effect.fail(new McpResponseTooLarge())
28	              : Effect.succeed([next, [chunk]] as const);
29	          }
30	        ),
31	        Stream.mkUint8Array,
32	        Effect.map((bytes) =>
33	          HttpServerResponse.uint8Array(bytes, {
34	            cookies: response.cookies,
35	            headers: response.headers,
36	            status: response.status,
37	            statusText: response.statusText,
38	          })
39	        )
40	      )
41	    ),
42	    Effect.timeoutOption(McpResponseDeadline),
43	    Effect.catchCause((cause) =>
44	      Cause.hasInterrupts(cause) ? Effect.interrupt : Effect.succeedNone
45	    ),
46	    Effect.map(
47	      Option.getOrElse(() => HttpServerResponse.empty({ status: 503 }))
48	    )
49	  );
50	});
 1	export { withCalculatorRequestBodyLimit as withApiRequestBodyLimit } from "@taxkit/api-rpc/request-boundary";
 1	import { CalculatorHostTelemetryLive } from "@taxkit/api-rpc/host-telemetry";
 2	
 3	export const ApiSafeTelemetryLive = CalculatorHostTelemetryLive("api");
 1	import { CalculatorAdmission } from "@taxkit/calculators/admission.service";
 2	import {
 3	  CalculatorAdmissionUnavailable,
 4	  CalculatorRateLimited,
 5	} from "@taxkit/calculators/schemas";
 6	import { RateLimit } from "alchemy/Cloudflare/Workers";
 7	import { CurrentRuntimeContext, RuntimeContext } from "alchemy/RuntimeContext";
 8	import { Config, Effect, Layer, Redacted, Schema } from "effect";
 9	import { NetAddress } from "effect/net";
10	
11	const CalculatorRateNamespace = Schema.String.check(
12	  Schema.isPattern(/^[1-9]\d*$/u)
13	).pipe(Schema.brand("api/CalculatorRateNamespace"));
14	
15	// Config is captured by Alchemy's native planning/runtime bridge. The operator
16	// owns its account-wide unique stage value; no Production value is invented.
17	export const ApiCalculatorAdmission = Layer.effect(
18	  CalculatorAdmission,
19	  Effect.gen(function* () {
20	    const namespace = yield* Config.schema(
21	      CalculatorRateNamespace,
22	      "CALCULATOR_RATE_NAMESPACE"
23	    );
24	    const limiter = yield* RateLimit("CALCULATOR_RATE_LIMIT", {
25	      namespaceId: namespace,
26	      simple: { limit: 60, period: 60 },
27	    });
28	    const runtime = yield* CurrentRuntimeContext;
29	    if (runtime === undefined) {
30	      return CalculatorAdmission.of({
31	        admitCalculation: () =>
32	          Effect.fail(new CalculatorAdmissionUnavailable()),
33	      });
34	    }
35	    return CalculatorAdmission.of({
36	      admitCalculation: Effect.fn("CalculatorAdmission.admitCalculation")(
37	        (key) =>
38	          Effect.suspend(() =>
39	            limiter.limit({ key: NetAddress.formatIp(Redacted.value(key)) })
40	          ).pipe(
41	            Effect.provideService(RuntimeContext, runtime),
42	            Effect.flatMap(
43	              Schema.decodeUnknownEffect(
44	                Schema.Struct({ success: Schema.Boolean })
45	              )
46	            ),
47	            Effect.mapError(() => new CalculatorAdmissionUnavailable()),
48	            Effect.catchDefect(() =>
49	              Effect.fail(new CalculatorAdmissionUnavailable())
50	            ),
51	            Effect.flatMap((reply) =>
52	              reply.success
53	                ? Effect.void
54	                : Effect.fail(new CalculatorRateLimited())
55	            )
56	          )
57	      ),
58	    });
59	  })
60	);
