 1	import {
 2	  Config,
 3	  Context,
 4	  Effect,
 5	  Layer,
 6	  Option,
 7	  Schema,
 8	  SchemaTransformation,
 9	} from "effect";
10	
11	import {
12	  ApiServerConfigError,
13	  ApiServerConfigSchema,
14	  ApiServerConfigSourceSchema,
15	  ApiServerTcpAddressSchema,
16	} from "./schemas.js";
17	import type { ApiServerConfigService } from "./schemas.js";
18	
19	const defaultHost = "127.0.0.1";
20	const defaultPort = 4000;
21	
22	export class ApiServerConfig extends Context.Service<
23	  ApiServerConfig,
24	  ApiServerConfigService
25	>()("@taxkit/api/ServerConfig") {}
26	
27	const HostEnvironmentValue = Schema.String.pipe(
28	  Schema.decodeTo(
29	    ApiServerConfigSourceSchema.fields.host,
30	    SchemaTransformation.transform({
31	      decode: (host) => host.trim() || defaultHost,
32	      encode: (host) => host,
33	    })
34	  )
35	);
36	
37	// Config resolves the caller's provider. The live application uses the native
38	// environment provider; tests substitute it without changing ambient settings.
39	const loadApiServerConfig = Config.all({
40	  host: Config.schema(HostEnvironmentValue, "API_HOST").pipe(
41	    Config.withDefault(defaultHost)
42	  ),
43	  port: Config.schema(ApiServerConfigSourceSchema.fields.port, "API_PORT").pipe(
44	    Config.option,
45	    Config.flatMap(
46	      Option.match({
47	        onNone: () =>
48	          Config.schema(ApiServerConfigSourceSchema.fields.port, "PORT").pipe(
49	            Config.withDefault(defaultPort)
50	          ),
51	        onSome: Config.succeed,
52	      })
53	    )
54	  ),
55	}).pipe(
56	  Effect.mapError(() => new ApiServerConfigError({ operation: "settings" })),
57	  Effect.map((source) =>
58	    ApiServerConfigSchema.make({
59	      address: ApiServerTcpAddressSchema.make({
60	        hostname: source.host,
61	        port: source.port,
62	      }),
63	    })
64	  )
65	);
66	
67	export const ApiServerConfigLive = Layer.effect(
68	  ApiServerConfig,
69	  loadApiServerConfig
70	);
