  1	import {
  2	  CalculatorClientRateKey,
  3	  CalculatorRequestRateKey,
  4	} from "@taxkit/api-rpc/rate-identity";
  5	import { PublicCalculatorService } from "@taxkit/calculators/service";
  6	import { ContentService } from "@taxkit/content/service";
  7	import { DurableObject, DurableObjectState } from "alchemy/Cloudflare/Workers";
  8	import { safeHttpEffect } from "alchemy/Http";
  9	import type { HttpEffect } from "alchemy/Http";
 10	import type { RuntimeContext } from "alchemy/RuntimeContext";
 11	import {
 12	  Context,
 13	  DateTime,
 14	  Effect,
 15	  Exit,
 16	  Layer,
 17	  Option,
 18	  Redacted,
 19	  Ref,
 20	  Schema,
 21	  Scope,
 22	  Semaphore,
 23	  SynchronizedRef,
 24	} from "effect";
 25	import { McpProtocol } from "effect/ai";
 26	import {
 27	  Headers,
 28	  HttpRouter,
 29	  HttpServerRequest,
 30	  HttpServerResponse,
 31	} from "effect/http";
 32	import { NetAddress } from "effect/net";
 33	
 34	import {
 35	  ApiCalculatorDelivery,
 36	  withCalculatorAnalytics,
 37	} from "./analytics-request.boundary.js";
 38	import { ApiCalculatorEvents } from "./calculator-analytics.layer.js";
 39	import { McpRequestAbortSignal } from "./mcp-request.service.js";
 40	import { withBoundedMcpReply } from "./mcp-response.boundary.js";
 41	import {
 42	  McpSessionId,
 43	  McpSessionInitialisationLimit,
 44	  McpSessionLifetime,
 45	  McpSessionRequestLimit,
 46	} from "./mcp.schemas.js";
 47	import { TaxKitMcpHttpLayer } from "./mcp.tools.layer.js";
 48	import { ApiSafeTelemetryLive } from "./worker-telemetry.layer.js";
 49	import { ApiWorkerSettingsConfig } from "./worker.config.js";
 50	
 51	// The plain/in-process host keeps its modern-only composition. Only the
 52	// native composition supplies the private, stage-bound session namespace.
 53	export const McpSessionHost = Context.Reference<
 54	  Option.Option<{ readonly fetch: HttpEffect }>
 55	>("@taxkit/api/McpSessionHost", { defaultValue: Option.none });
 56	
 57	class TaxKitMcpSessions extends DurableObject<
 58	  TaxKitMcpSessions,
 59	  { readonly fetch: HttpEffect<RuntimeContext> }
 60	>()("TaxKitMcpSessions") {}
 61	
 62	const SessionRateHeader = "x-taxkit-mcp-calculator-key";
 63	
 64	// SDK registration captures these existing services. The SDK reconstructs
 65	// their graph in its native isolate; this is not a second implementation or
 66	// a global work pool. Native protocol parsing/session maps remain native.
 67	export const McpSessionHostLive = Layer.effect(
 68	  McpSessionHost,
 69	  Effect.gen(function* () {
 70	    const analytics = yield* ApiCalculatorDelivery;
 71	    const settings = yield* Effect.cached(ApiWorkerSettingsConfig);
 72	    const telemetry = yield* Layer.build(ApiSafeTelemetryLive);
 73	    const calculator = Layer.succeed(
 74	      PublicCalculatorService,
 75	      yield* PublicCalculatorService
 76	    );
 77	    const content = Layer.succeed(ContentService, yield* ContentService);
 78	    const namespace = yield* TaxKitMcpSessions.pipe(
 79	      Effect.provide(
 80	        TaxKitMcpSessions.make(
 81	          Effect.gen(function* () {
 82	            const state = yield* DurableObjectState;
 83	            return Effect.gen(function* () {
 84	              // A whole native host Scope is the supported expiry boundary. The
 85	              // adapter provides no public per-session removal operation.
 86	              const makeHost = Effect.gen(function* () {
 87	                const config = yield* settings.pipe(Effect.orDie);
 88	                const expires = DateTime.addDuration(
 89	                  yield* DateTime.now,
 90	                  McpSessionLifetime
 91	                );
 92	                const scope = yield* Scope.make();
 93	                return yield* Effect.gen(function* () {
 94	                  const handler = yield* HttpRouter.toHttpEffect(
 95	                    TaxKitMcpHttpLayer(
 96	                      config.websiteOrigin,
 97	                      McpProtocol.v2025_11_25
 98	                    ).pipe(Layer.provide(calculator), Layer.provide(content))
 99	                  ).pipe(
100	                    Scope.provide(scope),
101	                    Effect.provideContext(telemetry),
102	                    Effect.orDie
103	                  );
104	                  const initialisations = yield* Ref.make(0);
105	                  // Only the expiry timestamp is stored by the native alarm API.
106	                  yield* state.storage.setAlarm(
107	                    DateTime.toEpochMillis(expires)
108	                  );
109	                  return { expires, handler, initialisations, scope } as const;
110	                }).pipe(
111	                  Effect.onExit((exit) =>
112	                    Exit.isFailure(exit)
113	                      ? Scope.close(scope, exit)
114	                      : Effect.void
115	                  )
116	                );
117	              }).pipe(
118	                Effect.updateContext(
119	                  (context: Context.Context<RuntimeContext>) =>
120	                    Context.omit(
121	                      ApiCalculatorEvents,
122	                      CalculatorRequestRateKey,
123	                      McpRequestAbortSignal,
124	                      HttpServerRequest.HttpServerRequest
125	                    )(context)
126	                )
127	              );
128	              const host = yield* SynchronizedRef.make(
129	                Option.none<Effect.Success<typeof makeHost>>()
130	              );
131	              const requests = yield* Semaphore.make(McpSessionRequestLimit);
132	              const expire = Effect.gen(function* () {
133	                const now = yield* DateTime.now;
134	                return yield* SynchronizedRef.modifyEffect(host, (current) =>
135	                  Option.match(current, {
136	                    onNone: () =>
137	                      Effect.succeed([undefined, Option.none()] as const),
138	                    onSome: (value) =>
139	                      DateTime.isGreaterThanOrEqualTo(now, value.expires)
140	                        ? Scope.close(value.scope, Exit.void).pipe(
141	                            Effect.as([undefined, Option.none()] as const)
142	                          )
143	                        : state.storage
144	                            .setAlarm(DateTime.toEpochMillis(value.expires))
145	                            .pipe(Effect.as([undefined, current] as const)),
146	                  })
147	                );
148	              });
149	
150	              const fetch = Effect.gen(function* () {
151	                const request = yield* HttpServerRequest.HttpServerRequest;
152	                const config = yield* settings.pipe(Effect.orDie);
153	                if (
154	                  new URL(request.url, config.apiOrigin).pathname !== "/mcp"
155	                ) {
156	                  return HttpServerResponse.empty({ status: 404 });
157	                }
158	                // Origin refusal precedes admission and native state allocation.
159	                const origin = Headers.get(request.headers, "origin");
160	                if (
161	                  Option.isSome(origin) &&
162	                  origin.value !== config.websiteOrigin.origin
163	                ) {
164	                  return HttpServerResponse.empty({ status: 403 });
165	                }
166	                const rawId = Headers.get(request.headers, "mcp-session-id");
167	                if (
168	                  Option.isSome(rawId) &&
169	                  Option.isNone(
170	                    Schema.decodeUnknownOption(McpSessionId)(rawId.value)
171	                  )
172	                ) {
173	                  return HttpServerResponse.empty({ status: 404 });
174	                }
175	                // Native session streams/subscriptions are outside this closed
176	                // tool contract. POST cancellation notifications still work.
177	                if (request.method !== "POST") {
178	                  return HttpServerResponse.empty({ status: 405 });
179	                }
180	                const now = yield* DateTime.now;
181	                const selected = yield* SynchronizedRef.modifyEffect(
182	                  host,
183	                  (current) =>
184	                    Effect.gen(function* () {
185	                      if (
186	                        Option.isSome(current) &&
187	                        DateTime.isGreaterThanOrEqualTo(
188	                          now,
189	                          current.value.expires
190	                        )
191	                      ) {
192	                        yield* Scope.close(current.value.scope, Exit.void);
193	                      }
194	                      const active = Option.filter(current, (value) =>
195	                        DateTime.isLessThan(now, value.expires)
196	                      );
197	                      if (Option.isSome(active)) {
198	                        return [active, active] as const;
199	                      }
200	                      // An expired/unknown conversation cannot create a host.
201	                      if (Option.isSome(rawId)) {
202	                        return [Option.none(), Option.none()] as const;
203	                      }
204	                      const created = Option.some(yield* makeHost);
205	                      return [created, created] as const;
206	                    })
207	                );
208	                if (Option.isNone(selected)) {
209	                  return HttpServerResponse.empty({ status: 404 });
210	                }
211	                const active = selected.value;
212	                if (Option.isNone(rawId)) {
213	                  const admitted = yield* Ref.modify(
214	                    active.initialisations,
215	                    (count) =>
216	                      count < McpSessionInitialisationLimit
217	                        ? ([true, count + 1] as const)
218	                        : ([false, count] as const)
219	                  );
220	                  if (!admitted) {
221	                    return HttpServerResponse.empty({
222	                      headers: {
223	                        "retry-after": String(
224	                          Math.max(
225	                            1,
226	                            Math.ceil(
227	                              (DateTime.toEpochMillis(active.expires) -
228	                                DateTime.toEpochMillis(now)) /
229	                                1000
230	                            )
231	                          )
232	                        ),
233	                      },
234	                      status: 429,
235	                    });
236	                  }
237	                }
238	                const key = Headers.get(
239	                  request.headers,
240	                  SessionRateHeader
241	                ).pipe(
242	                  Option.flatMap(
243	                    Schema.decodeUnknownOption(CalculatorClientRateKey)
244	                  )
245	                );
246	                return yield* withCalculatorAnalytics(
247	                  withBoundedMcpReply(active.handler)
248	                ).pipe(
249	                  Effect.provideService(ApiCalculatorDelivery, analytics),
250	                  Effect.provideService(CalculatorRequestRateKey, key),
251	                  Effect.provideService(
252	                    McpRequestAbortSignal,
253	                    Schema.decodeUnknownOption(Schema.instanceOf(Request))(
254	                      request.source
255	                    ).pipe(Option.map((source) => source.signal))
256	                  )
257	                );
258	              }).pipe(
259	                requests.withPermitsIfAvailable(1),
260	                Effect.map(
261	                  Option.getOrElse(() =>
262	                    HttpServerResponse.empty({ status: 503 })
263	                  )
264	                ),
265	                safeHttpEffect,
266	                Effect.provideContext(telemetry)
267	              );
268	              return {
269	                alarm: () => expire,
270	                fetch,
271	              };
272	            });
273	          })
274	        )
275	      )
276	    );
277	    const fetch = Effect.gen(function* () {
278	      const request = yield* HttpServerRequest.HttpServerRequest;
279	      const key = yield* CalculatorRequestRateKey;
280	      const headers = Headers.remove(request.headers, SessionRateHeader);
281	      const trusted = Option.isSome(key)
282	        ? Headers.set(
283	            headers,
284	            SessionRateHeader,
285	            NetAddress.formatIp(Redacted.value(key.value))
286	          )
287	        : headers;
288	      return yield* namespace
289	        .getByName("legacy-mcp-v2025-11-25")
290	        .fetch(request.modify({ headers: trusted }));
291	    });
292	    return Option.some({ fetch });
293	  })
294	);

 1	import { collectionPolicyFromHeaders } from "@taxkit/analytics/collection-policy";
 2	import type { CalculatorUse } from "@taxkit/analytics/schemas";
 3	import { BackendAnalytics } from "@taxkit/analytics/service";
 4	import {
 5	  DurableObjectState,
 6	  WorkerExecutionContext,
 7	} from "alchemy/Cloudflare/Workers";
 8	import type { HttpEffect } from "alchemy/Http";
 9	import { RuntimeContext } from "alchemy/RuntimeContext";
10	import { Context, Effect, Layer, Option, Ref } from "effect";
11	import { HttpServerRequest } from "effect/http";
12	
13	import { ApiCalculatorEvents } from "./calculator-analytics.layer.js";
14	
15	// Native host composition supplies capture. An in-process or local host
16	// deliberately has no background delivery; it must not borrow another runtime.
17	export const ApiCalculatorDelivery = Context.Reference<
18	  Option.Option<{
19	    readonly recordCalculatorUse: (input: CalculatorUse) => Effect.Effect<void>;
20	  }>
21	>("@taxkit/api/ApiCalculatorDelivery", { defaultValue: Option.none });
22	
23	export const ApiCalculatorDeliveryLive = Layer.effect(
24	  ApiCalculatorDelivery,
25	  Effect.gen(function* () {
26	    const analytics = yield* BackendAnalytics;
